#include <cstddef>
#include <iostream>
#include <memory>

class IntVector
{
public:
    void push_back(int value) {}
    std::size_t size() const { return m_size; }

private:
    std::unique_ptr<int[]> m_data{};
    std::size_t m_size{};
    std::size_t m_capacity{};
};

int main()
{
    IntVector v{};
    for (int i{0}; i < 1000; ++i) v.push_back(i);
    std::cout << v.size() << '\n';
}
